<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= lang('Sales.quote') ?> <?= esc($quote->quote_number) ?></title><style>body{font:16px Arial,sans-serif;color:#25313c;background:#f4f6f8;margin:0}.wrap{max-width:960px;margin:40px auto;padding:0 18px}.card{background:#fff;border:1px solid #e3e8ed;border-radius:8px;padding:28px;box-shadow:0 2px 8px #1d2b3a10}h1{font-size:25px;margin-top:0}.muted{color:#6a7783}.table{width:100%;border-collapse:collapse;margin:24px 0}.table th,.table td{padding:12px;border-bottom:1px solid #e6eaee;text-align:left}.table .num{text-align:right}.actions{display:flex;gap:10px;flex-wrap:wrap}.btn{border:0;border-radius:4px;padding:10px 16px;color:#fff;text-decoration:none;cursor:pointer}.green{background:#23966d}.red{background:#c95151}.blue{background:#287db4}.gray{background:#687985}textarea{width:100%;box-sizing:border-box;min-height:75px;margin:8px 0 14px;border:1px solid #cfd7de;border-radius:4px;padding:9px}</style></head><body><div class="wrap"><div class="card">
    <?php if (! empty($config['company'])): ?><p class="muted"><?= esc($config['company']) ?></p><?php endif; ?><h1><?= lang('Sales.quote') ?> <?= esc($quote->quote_number) ?></h1>
    <?php if (session()->getFlashdata('error')): ?><div class="alert alert-danger"><?= esc(session()->getFlashdata('error')) ?></div><?php endif; ?>
    <?php if (session()->getFlashdata('message')): ?><div class="alert alert-success"><?= esc(session()->getFlashdata('message')) ?></div><?php endif; ?>
    <p class="muted"><?= esc($quote->customer_name) ?> · <?= esc($quote->salesperson_name) ?> · <?= lang('Quotations.valid_until') ?>: <?= esc($quote->valid_until) ?></p>
    <p><?= lang('Quotations.status') ?>: <strong><?= lang('Quotations.status_' . $quote->status) ?></strong></p>
    <table class="table"><thead><tr><th><?= lang('Quotations.description') ?></th><th><?= lang('Quotations.quantity') ?></th><th><?= lang('Quotations.unit_price') ?></th><th class="num"><?= lang('Quotations.total') ?></th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= esc($item->item_name ?: $item->description) ?></td><td><?= esc($item->quantity_purchased) ?></td><td><?= to_currency($item->item_unit_price) ?></td><td class="num"><?= to_currency(($item->discount_type === PERCENT ? $item->quantity_purchased * $item->item_unit_price * (1 - $item->discount / 100) : $item->quantity_purchased * ($item->item_unit_price - $item->discount))) ?></td></tr><?php endforeach; ?><?php foreach ($taxes as $tax): ?><tr><td colspan="3"><?= esc($tax->name ?: $tax->tax_group) ?> (<?= esc($tax->tax_rate) ?>%)</td><td class="num"><?= to_currency($tax->sale_tax_amount) ?></td></tr><?php endforeach; ?></tbody></table>
    <p class="muted" style="text-align:right"><strong><?= lang('Sales.total') ?>: <?= to_currency($total) ?></strong></p>
    <?php if ($options): ?><h3><?= lang('Quotations.optional_items') ?></h3><?php foreach ($options as $option): ?><p><?= esc($option->description) ?> — <?= esc($option->quantity) ?> × <?= to_currency($option->unit_price) ?> <?= esc($option->notes) ?></p><?php endforeach; ?><?php endif; ?>
    <?php foreach ($attachments as $attachment): ?><p><a href="<?= site_url('quotation/attachment/' . $quote->public_token . '/' . (int) $attachment->quotation_attachment_id) ?>"><?= esc($attachment->file_name) ?></a></p><?php endforeach; ?>
    <div class="actions"><a class="btn blue" href="<?= site_url('quotation/pdf/' . $quote->public_token) ?>"><?= lang('Quotations.download_pdf') ?></a></div>
    <?php if (in_array($quote->status, ['sent', 'viewed'], true) && $quote->valid_until >= date('Y-m-d')): ?>
        <?= form_open('quotation/respond/' . $quote->public_token) ?><label for="comment"><?= lang('Quotations.customer_comment') ?></label><textarea id="comment" name="comment"></textarea><div class="actions"><button class="btn green" name="action" value="accept"><?= lang('Quotations.accept') ?></button><button class="btn red" name="action" value="reject"><?= lang('Quotations.reject') ?></button><button class="btn gray" name="action" value="request_revision"><?= lang('Quotations.request_revision') ?></button></div><?= form_close() ?>
    <?php endif; ?>
</div></div></body></html>
